<?php require '/etc/cei-labs/natas-runtime/natas31.php'; $artifact = isset($_POST['artifact']) && is_string($_POST['artifact']) ? $_POST['artifact'] : ''; $allowed = array('brief.txt' => 'training-brief', 'handoff.note' => 'handoff-note'); $ok = strlen($artifact) <= 32 && isset($allowed[$artifact]) && $artifact === 'handoff.note'; ?><!doctype html><html><body><h1>Virtual multipart artifact</h1><p>This modern form selects a named training artifact from an allowlist; uploads and paths are not accepted.</p><form method="post"><input name="artifact" maxlength="32"><button>Select</button></form><?php if ($ok): ?><p>Artifact handoff: <?php echo htmlspecialchars($natas32_secret, ENT_QUOTES, 'UTF-8'); ?></p><?php else: ?><p>No assigned artifact.</p><?php endif; ?></body></html>
